<?php
namespace App\Http\Controllers;

use App\Services\{Content,Settings,StudioDocuments};
use App\Support\Json;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Validator};
use Illuminate\Support\Str;

final class StudioApiController extends Controller {
    public function __construct(private StudioDocuments $documents,private Settings $settings){}
    private function actor(Request $r): int {return (int)$r->attributes->get('studio_admin')->id;}
    private function audit(Request $r,string $action,?string $id=null): void {$this->settings->audit($this->actor($r),'studio.'.$action,$id);}
    public function schema(Request $r){return response()->json(['service'=>'puzzlequest_studio','api_version'=>'1','backend_version'=>app(\App\Services\Updates::class)->version(),'kinds'=>StudioDocuments::KINDS,'piece_counts'=>[16,36,64,100],'package_format'=>['level.json','manifest.json'],'limits'=>['media_max_kb'=>8192,'document_max_bytes'=>131072],'role'=>$r->attributes->get('studio_admin')->role]);}
    public function worlds(){return response()->json(['items'=>DB::table('worlds')->orderBy('position')->get()->map(fn($w)=>['id'=>$w->id,'title'=>Json::read($w->title),'position'=>(int)$w->position,'published'=>(bool)$w->published])->all()]);}
    public function createWorld(Request $r){$d=$r->validate(['id'=>'required|regex:/^[a-z0-9_]{3,80}$/D|unique:worlds,id','title'=>'required|array','title.ar'=>'required|string|max:120','title.en'=>'required|string|max:120','position'=>'required|integer|between:1,100000']);DB::table('worlds')->insert(['id'=>$d['id'],'title'=>Json::encode($d['title']),'position'=>$d['position'],'published'=>false,'created_at'=>now(),'updated_at'=>now()]);$this->audit($r,'world.create',$d['id']);return response()->json(['id'=>$d['id'],'published'=>false],201);}
    public function updateWorld(Request $r,string $id){$w=DB::table('worlds')->where('id',$id)->first();abort_unless($w,404);$d=$r->validate(['title'=>'required|array','title.ar'=>'required|string|max:120','title.en'=>'required|string|max:120','position'=>'required|integer|between:1,100000','published'=>'required|boolean']);if($d['published']&&!DB::table('levels')->where('world_id',$id)->where('published',true)->exists())return response()->json(['error'=>'world_requires_published_level'],422);if($w->published&&$w->position!=$d['position'])return response()->json(['error'=>'published_world_reordering_requires_migration'],409);
        DB::table('worlds')->where('id',$id)->update(['title'=>Json::encode($d['title']),'position'=>$d['position'],'published'=>$d['published'],'updated_at'=>now()]);$this->audit($r,'world.update',$id);return response()->json(['id'=>$id,'published'=>(bool)$d['published']]);}
    public function levels(Request $r){$q=DB::table('levels')->orderBy('world_id')->orderBy('position');if($r->query('world_id'))$q->where('world_id',$r->query('world_id'));return response()->json(['items'=>$q->limit(1000)->get()->map(fn($x)=>['id'=>$x->id,'world_id'=>$x->world_id,'display_code'=>$x->display_code,'title'=>Json::read($x->title),'position'=>(int)$x->position,'previous_level_id'=>$x->previous_level_id,'published'=>(bool)$x->published,'active_revision_id'=>$x->active_revision_id])->all()]);}
    public function createLevel(Request $r){$d=$r->validate(['id'=>'required|regex:/^[a-z0-9_]{3,100}$/D|unique:levels,id','world_id'=>'required|exists:worlds,id','display_code'=>'required|regex:/^[0-9]+-[0-9]+$/D|unique:levels,display_code','position'=>'required|integer|between:1,100000','title'=>'required|array','title.ar'=>'required|string|max:120','title.en'=>'required|string|max:120','previous_level_id'=>'nullable|exists:levels,id']);$conflict=DB::table('levels')->where('world_id',$d['world_id'])->where('position',$d['position'])->exists();if($conflict)return response()->json(['error'=>'world_position_already_used'],409);
        if(!empty($d['previous_level_id'])&&DB::table('levels')->where('id',$d['previous_level_id'])->value('world_id')!==$d['world_id'])return response()->json(['error'=>'previous_level_must_be_in_same_world'],422);
        DB::table('levels')->insert(['id'=>$d['id'],'world_id'=>$d['world_id'],'display_code'=>$d['display_code'],'position'=>$d['position'],'title'=>Json::encode($d['title']),'previous_level_id'=>$d['previous_level_id']??null,'published'=>false,'created_at'=>now(),'updated_at'=>now()]);$this->audit($r,'level.create',$d['id']);return response()->json(['id'=>$d['id'],'published'=>false],201);}
    public function updateLevel(Request $r,string $id){$level=DB::table('levels')->where('id',$id)->first();abort_unless($level,404);$d=$r->validate(['title'=>'required|array','title.ar'=>'required|string|max:120','title.en'=>'required|string|max:120','position'=>'required|integer|between:1,100000','previous_level_id'=>'nullable|exists:levels,id']);if($level->published&&($level->position!=$d['position']||($level->previous_level_id??null)!==($d['previous_level_id']??null)))return response()->json(['error'=>'published_level_structural_change_blocked'],409);
        if(DB::table('levels')->where('world_id',$level->world_id)->where('position',$d['position'])->where('id','!=',$id)->exists())return response()->json(['error'=>'world_position_already_used'],409);
        if(!empty($d['previous_level_id'])&&($d['previous_level_id']===$id||DB::table('levels')->where('id',$d['previous_level_id'])->value('world_id')!==$level->world_id))return response()->json(['error'=>'invalid_previous_level'],422);
        DB::table('levels')->where('id',$id)->update(['title'=>Json::encode($d['title']),'position'=>$d['position'],'previous_level_id'=>$d['previous_level_id']??null,'updated_at'=>now()]);$this->audit($r,'level.update',$id);return response()->json(['id'=>$id]);}
    public function unpublishLevel(Request $r,string $id){abort_unless(DB::table('levels')->where('id',$id)->exists(),404);DB::table('levels')->where('id',$id)->update(['published'=>false,'updated_at'=>now()]);$this->audit($r,'level.unpublish',$id);return response()->json(['id'=>$id,'published'=>false]);}
    public function revisions(Request $r){$q=DB::table('content_revisions')->orderByDesc('created_at');if($r->query('level_id'))$q->where('level_id',$r->query('level_id'));return response()->json(['items'=>$q->limit(100)->get(['id','level_id','revision','state','published_at'])->all()]);}
    public function importLevel(Request $r){$d=$r->validate(['archive'=>'required|file|max:131072']);$result=app(Content::class)->import($d['archive']->getRealPath());$this->audit($r,'level.import',$result['id']);return response()->json($result,201);}
    public function publishLevel(Request $r,string $id){$d=$r->validate(['device_qa_approved'=>'required|accepted']);DB::transaction(fn()=>app(Content::class)->publish($id,true));$this->audit($r,'level.publish',$id);return response()->json(['id'=>$id,'state'=>'published']);}
    public function documentList(Request $r,string $kind){return response()->json(['items'=>$this->documents->index($kind,$r->query('world_id'))]);}
    private function documentInput(Request $r,bool $create): array {return $r->validate(['kind'=>$create?'required|in:'.implode(',',StudioDocuments::KINDS):'prohibited','slug'=>$create?'required|regex:/^[a-z0-9_-]{3,80}$/D':'prohibited','world_id'=>'nullable|exists:worlds,id','title'=>'required|array','title.ar'=>'required|string|max:120','title.en'=>'required|string|max:120','position'=>'required|integer|between:1,100000','payload'=>'present|array','draft_revision'=>$create?'prohibited':'required|integer|min:1']);}
    public function createDocument(Request $r){$d=$this->documentInput($r,true);if(DB::table('studio_documents')->where('kind',$d['kind'])->where('slug',$d['slug'])->exists())return response()->json(['error'=>'document_slug_exists'],409);$created=$this->documents->create($d,$this->actor($r));$this->audit($r,'document.create',$created['id']);return response()->json($created,201);}
    public function updateDocument(Request $r,string $id){$d=$this->documentInput($r,false);$item=$this->documents->edit($id,$d,(int)$d['draft_revision']);$this->audit($r,'document.update',$id);return response()->json($item);}
    public function publishDocument(Request $r,string $id){$d=$r->validate(['draft_revision'=>'required|integer|min:1','content_qa_approved'=>'required|accepted']);$item=$this->documents->publish($id,$this->actor($r),(int)$d['draft_revision']);$this->audit($r,'document.publish',$id);return response()->json($item);}
    public function restoreDocument(Request $r,string $id,int $revision){$d=$r->validate(['draft_revision'=>'required|integer|min:1']);$item=$this->documents->restoreToDraft($id,$revision,(int)$d['draft_revision']);$this->audit($r,'document.restore_draft',$id);return response()->json($item);}
    public function retireDocument(Request $r,string $id){$item=$this->documents->retire($id);$this->audit($r,'document.retire',$id);return response()->json($item);}
    public function history(string $id){abort_unless(DB::table('studio_documents')->where('id',$id)->exists(),404);return response()->json(['items'=>DB::table('studio_document_history')->where('document_id',$id)->orderByDesc('revision')->get(['id','revision','published_at'])->all()]);}
    public function media(){return response()->json(['items'=>DB::table('studio_media')->orderByDesc('created_at')->limit(500)->get()->map(fn($a)=>$this->mediaRecord($a))->all()]);}
    private function mediaRecord(object $a): array {return ['id'=>$a->id,'url'=>url('studio-media/'.basename($a->relative_path)),'width'=>(int)$a->width,'height'=>(int)$a->height,'mime'=>$a->mime,'sha256'=>$a->sha256,'bytes'=>(int)$a->bytes,'created_at'=>$a->created_at];}
    public function uploadMedia(Request $r){$d=$r->validate(['image'=>'required|file|max:8192']);$file=$d['image'];$path=$file->getRealPath();$info=@getimagesize($path);if(!$info||!in_array($info['mime'],['image/png','image/jpeg','image/webp'],true)||$info[0]<16||$info[1]<16||$info[0]*$info[1]>12000000)return response()->json(['error'=>'invalid_image_or_dimensions'],422);
        if(!function_exists('imagecreatefromstring'))return response()->json(['error'=>'gd_not_enabled'],503);
        $body=file_get_contents($path);$probe=@imagecreatefromstring($body);if(!$probe)return response()->json(['error'=>'corrupted_image'],422);imagedestroy($probe);
        $extension=match($info['mime']){'image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'};$id=(string)Str::uuid();$name=$id.'.'.$extension;$dir=public_path('studio-media');if(!is_dir($dir)&&!mkdir($dir,0755,true))abort(500,'Media directory unavailable');$destination=$dir.'/'.$name;if(!file_put_contents($destination,$body,LOCK_EX))abort(500,'Media write failed');chmod($destination,0644);
        DB::table('studio_media')->insert(['id'=>$id,'relative_path'=>'studio-media/'.$name,'mime'=>$info['mime'],'width'=>$info[0],'height'=>$info[1],'bytes'=>strlen($body),'sha256'=>hash('sha256',$body),'created_by'=>$this->actor($r),'created_at'=>now()]);$this->audit($r,'media.upload',$id);return response()->json($this->mediaRecord(DB::table('studio_media')->where('id',$id)->first()),201);
    }
    public function publicCatalog(Request $r){return response()->json($this->documents->publicCatalog($r->query('kind')))->header('Cache-Control','public, max-age=60');}
}
